/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
import { multiParams as P } from '../../../src/explore/multi/params';
import { exSanitizeName, exCharNorm, exVehNorm } from '../../../src/explore/multi/protocol';
import type { ServerMsg, Flyer, Kind } from '../../../src/explore/multi/protocol';
import { exIsBad } from './badwords';

export type Out = { to: string | 'all'; msg: ServerMsg };

// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; người lái: [slot, x, y, z, yaw, v, st, giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
// ch: nhân vật người đi dạo / người đi xe máy chọn (0 nam, 1 nữ), dùng ở nhóm đi dạo và chỗ lái xe máy; phát kèm walkers / drivers của lobby để mọi khách (cả người vào sau) vẽ đúng
// veh: loại xe của chỗ lái (0 ô tô, 1 xe máy), chỉ dùng ở nhóm lái; ô tô luôn ch 0
interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean; ch: number; veh: number }
interface Conn { stamps: number[] }

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]

export class SkyRoom {
  private conns = new Map<string, Conn>();
  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
  private driveSlots: (Slot | null)[] = new Array(P.drive.slots).fill(null);   // nhóm chỗ lái xe, tách khỏi hai nhóm kia
  private lastBroadcast = -Infinity;

  private lobby(): Out {
    const flyers: Flyer[] = [];
    const walkers: Flyer[] = [];
    const drivers: Flyer[] = [];
    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name, ch: s.ch }); });
    this.driveSlots.forEach((s, i) => { if (s) drivers.push({ slot: i, name: s.name, ch: s.ch, veh: s.veh }); });   // khách cũ bỏ qua ch / veh
    return { to: 'all', msg: { t: 'lobby', flyers, walkers, drivers } };
  }

  connect(id: string, now: number): Out[] | null {
    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
    this.conns.set(id, { stamps: [] });
    return [{ to: id, msg: this.lobby().msg }];
  }

  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay

  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo

  driveSlotOf(id: string): number { return this.driveSlots.findIndex(s => s !== null && s.id === id); }   // slot lái xe, -1 nếu không lái

  chOf(id: string): number { const w = this.walkSlotOf(id); if (w >= 0) return this.walkSlots[w].ch; const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].ch; }   // nhân vật của người đi dạo / đi xe máy (để lưu vào attachment); 0 nếu không

  vehOf(id: string): number { const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].veh; }   // loại xe của người lái (để lưu vào attachment); 0 nếu ô tô hoặc không lái

  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : this.driveSlotOf(id) >= 0 ? 'drive' : null; }

  hasFlyers(): boolean { return [this.slots, this.walkSlots, this.driveSlots].some(g => g.some(s => s !== null)); }   // còn ai giữ slot (bay, đi hoặc lái): giữ alarm quét

  private groupOf(kind: Kind | null): (Slot | null)[] { return kind === 'walk' ? this.walkSlots : kind === 'drive' ? this.driveSlots : this.slots; }

  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
  seenOf(id: string): number {
    const i = this.slotOf(id);
    if (i >= 0) return this.slots[i].seen;
    const w = this.walkSlotOf(id);
    if (w >= 0) return this.walkSlots[w].seen;
    const d = this.driveSlotOf(id);
    return d < 0 ? -1 : this.driveSlots[d].seen;
  }

  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number; veh?: number }[], now: number): void {
    for (const e of list) {
      const group = this.groupOf(e.kind === 'walk' || e.kind === 'drive' ? e.kind : 'fly');
      if (e.slot < 0 || e.slot >= group.length) continue;
      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
      const veh = e.kind === 'drive' ? exVehNorm(e.veh) : 0;   // attachment cũ không có veh: ô tô
      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false, ch: e.kind === 'walk' || veh === 1 ? exCharNorm(e.ch) : 0, veh };
    }
  }

  message(id: string, raw: string, now: number): Out[] {
    const conn = this.conns.get(id);
    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
    let m: any;
    try { m = JSON.parse(raw); } catch { return []; }
    if (!m || typeof m !== 'object') return [];
    const kind = this.kindOf(id);   // loại theo slot kết nối đang giữ, không theo trường trong gói
    const group = this.groupOf(kind);
    const slot = kind === null ? -1 : group.findIndex(s => s !== null && s.id === id);
    switch (m.t) {
      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk' || m.kind === 'drive' ? m.kind : 'fly', m.ch, m.veh, now);
      case 'leave': return this.release(id) ? [this.lobby()] : [];
      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind, m, now) : [];
      default: return [];
    }
  }

  // kind 'fly': tin trả lời không có trường kind (khách cũ hiểu được); 'walk' / 'drive' kèm kind; joined của 'drive' luôn vọng veh (khách xe máy dựa vào đó biết máy chủ hiểu xe máy)
  private onJoin(id: string, holding: boolean, rawName: unknown, kind: Kind, rawCh: unknown, rawVeh: unknown, now: number): Out[] {
    if (holding) return [];
    const k = kind === 'fly' ? {} : { kind };
    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
    if (name === null || exIsBad(name)) return [{ to: id, msg: { t: 'rejected', why: 'name', ...k } }];
    const group = this.groupOf(kind);
    const free = group.findIndex(s => s === null);
    if (free < 0) return [{ to: id, msg: { t: 'rejected', why: 'full', ...k } }];
    const veh = kind === 'drive' ? exVehNorm(rawVeh) : 0;   // khách cũ không gửi veh: ô tô
    group[free] = { id, name, seen: now, pos: null, dirty: false, ch: kind === 'walk' || veh === 1 ? exCharNorm(rawCh) : 0, veh };   // khách cũ không gửi ch: nam (đúng nhân vật họ tự thấy)
    return [{ to: id, msg: kind === 'drive' ? { t: 'joined', slot: free, kind, veh } : { t: 'joined', slot: free, ...k } }, this.lobby()];
  }

  private onPos(conn: Conn, s: Slot, slot: number, kind: Kind, m: any, now: number): Out[] {
    const { x, y, z, yaw, ts } = m;
    const walk = kind === 'walk', drive = kind === 'drive';
    const tilt = drive ? m.v : walk ? m.pose : m.bank;   // người lái gửi v + st, người đi dạo gửi pose, người bay gửi bank; trường của loại khác bị bỏ qua
    const st = drive ? m.st : 0;
    for (const v of [x, y, z, yaw, tilt, st]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
    conn.stamps = conn.stamps.filter(t => now - t < 1000);
    if (conn.stamps.length >= P.posMaxPerSec) return [];
    conn.stamps.push(now);
    s.seen = now;
    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
    if (drive) {
      const D = P.drive, B = D.bounds;
      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, D.yMin, D.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(tilt, -D.vMax, D.vMax), clamp(st, -D.steerMax, D.steerMax), stamp];
    } else if (walk) {
      const B = P.stroll.bounds;
      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
    } else {
      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
    }
    s.dirty = true;
    return this.flush(now);
  }

  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
  private flush(now: number): Out[] {
    if (now - this.lastBroadcast < P.broadcastMs) return [];
    const f: number[][] = [], w: number[][] = [], d: number[][] = [];
    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
    for (const t of this.walkSlots) if (t && t.dirty) { w.push(t.pos!); t.dirty = false; }
    for (const t of this.driveSlots) if (t && t.dirty) { d.push(t.pos!); t.dirty = false; }
    if (!f.length && !w.length && !d.length) return [];
    this.lastBroadcast = now;
    // f luôn có (khách cũ đọc m.f); w / d chỉ có khi có người cử động, khách cũ bỏ qua trường lạ
    const msg: { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] } = { t: 'pos', f };
    if (w.length) msg.w = w;
    if (d.length) msg.d = d;
    return [{ to: 'all', msg }];
  }

  // Trả slot của kết nối; true nếu có slot được trả
  private release(id: string): boolean {
    const i = this.slotOf(id);
    if (i >= 0) { this.slots[i] = null; return true; }
    const w = this.walkSlotOf(id);
    if (w >= 0) { this.walkSlots[w] = null; return true; }
    const d = this.driveSlotOf(id);
    if (d < 0) return false;
    this.driveSlots[d] = null;
    return true;
  }

  disconnect(id: string): Out[] {
    this.conns.delete(id);
    return this.release(id) ? [this.lobby()] : [];
  }

  sweep(now: number): Out[] {
    const out: Out[] = [];
    for (const group of [this.slots, this.walkSlots, this.driveSlots]) group.forEach((s, i) => {
      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); group[i] = null; }
    });
    if (out.length) out.push(this.lobby());
    return out;
  }
}
/* ===== Worker + Durable Object phòng bầu trời chung: bọc SkyRoom, WebSocket hibernation ===== */
import { multiParams as P } from '../../../src/explore/multi/params';
import { SkyRoom } from './room';
import type { Out } from './room';

interface Env { SKY: DurableObjectNamespace; ALLOWED_ORIGINS: string }
interface Att { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number; veh?: number }   // seen: giờ có tin cuối của người giữ slot, ghi thưa (mỗi heartbeatMs) để sống sót qua hibernation; kind: 'walk' = slot nằm ở nhóm đi dạo, 'drive' = nhóm lái xe, không có = nhóm bay; ch: nhân vật người đi dạo / đi xe máy chọn (chỉ ghi khi khác 0); veh: 1 = chỗ lái xe máy (chỉ ghi khi khác 0)

// So khớp scheme + hostname, bỏ cổng
function originKey(o: string): string | null {
  try { const u = new URL(o); return u.protocol + '//' + u.hostname; } catch { return null; }
}

// Mục cho phép có '*' (vd. bản xem trước PR của Netlify): '*' chỉ khớp một đoạn chữ thường/số, không có '.' hay '-'
function originAllowed(key: string, pattern: string): boolean {
  const p = originKey(pattern.replace(/\*/g, 'x'));
  if (!p) return false;
  if (!pattern.includes('*')) return p === key;
  const re = new RegExp('^' + pattern.trim().split('*').map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[a-z0-9]+') + '$');
  return re.test(key);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (url.pathname !== '/sky') return new Response('Not found', { status: 404 });
    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
    const key = originKey(req.headers.get('Origin') || '');
    if (!key || !env.ALLOWED_ORIGINS.split(',').some(s => originAllowed(key, s.trim()))) return new Response('Forbidden', { status: 403 });
    return env.SKY.get(env.SKY.idFromName('sky')).fetch(req);
  }
};

export class SkyObject implements DurableObject {
  private room = new SkyRoom();
  private names = new Map<number, string>();
  private walkNames = new Map<number, string>();   // tên người đi dạo theo slot, lấy từ walkers của lobby
  private driveNames = new Map<number, string>();  // tên người lái theo slot, lấy từ drivers của lobby
  private armed: boolean | null = null;   // đã đặt alarm chưa; null = chưa biết (vừa dựng hoặc vừa thức dậy): hỏi storage một lần

  constructor(private state: DurableObjectState, _env: Env) {
    // Đánh thức sau hibernation: dựng lại phòng từ attachment của từng socket
    const now = Date.now();
    const list: Att[] = [];
    for (const ws of this.state.getWebSockets()) {
      const a = ws.deserializeAttachment() as Att | null;
      if (!a) continue;
      this.room.connect(a.id, now);
      if (a.slot >= 0) list.push(a);
    }
    this.room.restore(list, now);
  }

  async fetch(_req: Request): Promise<Response> {
    const pair = new WebSocketPair();
    const [client, server] = [pair[0], pair[1]];
    const id = crypto.randomUUID();
    this.state.acceptWebSocket(server);
    server.serializeAttachment({ id, slot: -1, name: '' } as Att);
    const outs = this.room.connect(id, Date.now());
    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
    this.dispatch(outs);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
    const a = ws.deserializeAttachment() as Att | null;
    if (!a || typeof data !== 'string') return;
    this.dispatch(this.room.message(a.id, data, Date.now()));
    await this.armAlarm();
  }

  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }

  async alarm(): Promise<void> {
    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
    this.dispatch(this.room.sweep(Date.now()));
    await this.armAlarm();
  }

  private drop(ws: WebSocket): void {
    const a = ws.deserializeAttachment() as Att | null;
    if (a) this.dispatch(this.room.disconnect(a.id));
  }

  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
  private dispatch(outs: Out[]): void {
    const socks = this.state.getWebSockets();
    for (const o of outs) {
      const text = JSON.stringify(o.msg);
      for (const ws of socks) {
        const a = ws.deserializeAttachment() as Att | null;
        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
        try { ws.send(text); } catch { /* socket đã đóng */ }
      }
      if (o.msg.t === 'lobby') {
        this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
        this.walkNames = new Map((o.msg.walkers ?? []).map(f => [f.slot, f.name]));
        this.driveNames = new Map((o.msg.drivers ?? []).map(f => [f.slot, f.name]));
      }
    }
    for (const ws of socks) {
      const a = ws.deserializeAttachment() as Att | null;
      if (!a) continue;
      const kind = this.room.kindOf(a.id);
      const walk = kind === 'walk', drive = kind === 'drive';
      const slot = walk ? this.room.walkSlotOf(a.id) : drive ? this.room.driveSlotOf(a.id) : this.room.slotOf(a.id);
      const name = slot >= 0 ? ((walk ? this.walkNames : drive ? this.driveNames : this.names).get(slot) ?? a.name) : '';
      const seen = this.room.seenOf(a.id);
      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
      const k = walk ? 'walk' : drive ? 'drive' : undefined;   // loại ghi trong attachment; người bay không ghi (attachment như bản cũ)
      const ch = this.room.chOf(a.id), veh = this.room.vehOf(a.id);
      if (slot !== a.slot || name !== a.name || a.kind !== k || (a.ch ?? 0) !== ch || (a.veh ?? 0) !== veh || stale) {
        const next: Att = slot < 0 ? { id: a.id, slot, name } : k ? { id: a.id, slot, name, seen, kind: k } : { id: a.id, slot, name, seen };
        if (ch) next.ch = ch;
        if (veh) next.veh = veh;
        ws.serializeAttachment(next);
      }
    }
  }

  private async armAlarm(): Promise<void> {
    if (!this.room.hasFlyers() || this.armed) return;
    if (this.armed === null && (await this.state.storage.getAlarm()) !== null) { this.armed = true; return; }
    this.armed = true;
    try { await this.state.storage.setAlarm(Date.now() + P.sweepMs); } catch (e) { this.armed = false; throw e; }
  }
}
/* ===== Lọc tên tục (ngắn gọn, vi + en) ===== */
// Từ tục tiếng Việt có dấu: chặn khi là một từ riêng, viết đúng dấu (không lẫn với lớn, lợn, Các, Buổi, Bưởi)
const TONED = ['cặc', 'buồi', 'lồn'];
// Cùng các từ đó gõ không dấu: chỉ chặn khi cả tên đúng là từ đó (gõ không dấu thì không phân biệt được với từ thường)
const PLAIN = ['cac', 'buoi', 'lon'];
// Chặn khi là một từ riêng trong tên (hoặc cả tên khi bỏ ngăn cách: v.c.l); không chặn khi chỉ là một phần của từ (Grape, Dickson)
const WORD = ['dit', 'dm', 'dcm', 'dmm', 'dkm', 'vcl', 'vl', 'fag', 'sex', 'rape', 'dick'];
// Chặn khi xuất hiện ở bất kỳ đâu trong tên đã bỏ ngăn cách
const SUB = ['du ma', 'cutt', 'fuck', 'shit', 'bitch', 'cunt', 'pussy', 'asshole', 'nigger', 'nigga'];

// Hạ chữ thường; so từ có dấu trước, rồi bỏ dấu (đ → d), bỏ ký tự ngăn cách và tìm từ cấm
export function exIsBad(name: string): boolean {
  const low = name.toLowerCase().normalize('NFC');
  const tonedWords = low.split(/[^\p{L}\p{N}]+/u);
  if (TONED.some(b => tonedWords.includes(b)) || PLAIN.includes(tonedWords.join(''))) return true;
  const flat = low.replace(/đ/g, 'd').normalize('NFD').replace(/\p{M}/gu, '');
  const spaced = flat.replace(/[^a-z0-9]+/g, ' ').trim();
  const tight = spaced.replace(/ /g, '');
  const words = spaced.split(' ');
  return WORD.some(b => words.includes(b) || tight === b) || SUB.some(b => tight.includes(b.replace(/ /g, '')));
}
