import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string; kind?: 'walk' | 'drive'; ch?: number; veh?: number }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ). ch: nhân vật (0 nam, 1 nữ) của người đi dạo hoặc người đi xe máy; khách cũ không gửi = nam. veh: 1 = xe máy, chỉ kèm kind 'drive'; không có = ô tô (khách cũ)
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad; xe máy: bkLeanToWire(độ nghiêng)); không có bank / pose
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string; ch?: number; veh?: number }   // ch: nhân vật của người đi dạo / người đi xe máy (walkers, drivers; máy chủ cũ không gửi = nam); veh: loại xe (chỉ drivers; 1 xe máy, máy chủ cũ không gửi = ô tô)

/* Nhân vật đi dạo hợp lệ: 1 = nữ, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 nam */
export function exCharNorm(v: unknown): number { return v === 1 ? 1 : 0; }

/* Loại xe hợp lệ của chỗ lái: 1 = xe máy, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 ô tô */
export function exVehNorm(v: unknown): number { return v === 1 ? 1 : 0; }

/* Độ nghiêng xe máy qua trường st: máy chủ kẹp st ở ±drive.steerMax (0,56 rad, góc lái ô tô) nên gửi lean × BK_WIRE (độ nghiêng 0,7 rad vẫn lọt), bên nhận chia lại.
   Khách cũ thấy xe máy thành ô tô bẻ lái theo st (chấp nhận, spec §17.4). Số lạ (NaN) → 0 */
export const BK_WIRE = 0.8;
export function bkLeanToWire(lean: number): number {
  const w = lean * BK_WIRE, m = multiParams.drive.steerMax;
  return w > m ? m : w < -m ? -m : w === w ? w : 0;
}
export function bkLeanFromWire(st: number): number { return st === st ? st / BK_WIRE : 0; }

export type Kind = 'fly' | 'walk' | 'drive';

// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
// Đi dạo: lobby thêm walkers (flyers chỉ có người bay; mỗi người đi dạo kèm ch = nhân vật họ chọn, nên máy vào sau cũng biết ngay từ lobby đầu), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
// Xe máy (D-040): drivers kèm veh + ch, joined kind 'drive' luôn vọng veh; máy chủ cũ không vọng veh thì khách xe máy trả chỗ và lái một mình
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[] }
  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive'; veh?: number }
  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
  | { t: 'released' };

// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;

/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
export function exSanitizeName(raw: string): string | null {
  if (typeof raw !== 'string') return null;
  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let n = 0, cps = 0;
  for (const g of seg.segment(s)) {
    let k = 0;
    for (const _ of g.segment) k++;
    cps += k;
    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
  }
  return s;
}
/* ===== Dù lượn nhiều người: kết nối WebSocket tới máy chủ ===== */
import type { ClientMsg, ServerMsg } from './protocol';

export interface Transport {
  send(m: ClientMsg): void;
  close(): void;
  onMessage: (m: ServerMsg) => void;
  onClose: () => void;
}

// Mở WebSocket; reject khi lỗi hoặc quá hạn timeoutMs
export function exConnect(url: string, timeoutMs: number): Promise<Transport> {
  return new Promise<Transport>((resolve, reject) => {
    let ws: WebSocket;
    try { ws = new WebSocket(url); } catch (e) { reject(e); return; }
    let opened = false;
    let handler: ((m: ServerMsg) => void) | null = null;
    const pending: ServerMsg[] = [];   // tin tới trước khi người dùng gán onMessage (máy chủ gửi lobby ngay khi nhận kết nối) được giữ lại, không mất
    const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
    const t: Transport = {
      send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
      close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
      get onMessage() { return handler as (m: ServerMsg) => void; },
      set onMessage(fn: (m: ServerMsg) => void) { handler = fn; while (pending.length) fn(pending.shift() as ServerMsg); },
      onClose: () => {}
    };
    ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
    ws.onmessage = ev => {
      let m: ServerMsg;
      try { m = JSON.parse(String(ev.data)); } catch (e) { return; }
      if (m && typeof m.t === 'string') { if (handler) handler(m); else pending.push(m); }
    };
    ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
    ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
  });
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
import type { Flyer, Kind, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
  mySlot = -1;
  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  ch = 0;             // nhân vật mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' và join xe máy (sảnh và lời mời đều qua join())
  veh = 0;            // loại xe của phiên 'drive': 0 ô tô (gói join như khách cũ), 1 xe máy (join kèm veh + ch; máy chủ phải vọng veh trong joined)
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  onWalkPos: (w: number[][]) => void = () => {};
  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}

  /* Danh sách cùng loại với mình */
  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }

  /* Số chỗ của nhóm cùng loại */
  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
  join(name: string): void {
    this.name = name; this.notice = '';
    if (this.kind === 'drive' && this.first) return;
    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : this.kind === 'walk' ? { t: 'join', name, kind: 'walk', ch: this.ch }
      : this.veh === 1 ? { t: 'join', name, kind: 'drive', ch: this.ch, veh: 1 } : { t: 'join', name, kind: this.kind });
  }

  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.notice = 'released'; this.toWatching();
    this.onChange();
  }

  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
  }

  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
  }

  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
    if (this.phase !== 'flying') return;
    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
  private fixWatched(): void {
    const ids = this.peers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < this.cap;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  /* Máy chủ cũ (lobby đầu không có walkers / drivers, hoặc joined xe máy không vọng veh) không biết chỗ đi dạo / lái xe / xe máy: đóng kết nối, đi / lái một mình như khi không kết nối được */
  private offline(): void {
    const t = this.t;
    this.t = null;
    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
