61	export interface Flyer { slot: number; name: string; ch?: number; veh?: number }   // ch: nhân vật của người đi dạo / người đi xe máy (walkers, drivers; máy chủ cũ không gửi = nam); veh: loại xe (chỉ drivers; 1 xe máy, máy chủ cũ không gửi = ô tô)
