70	   Khách cũ thấy xe máy thành ô tô bẻ lái theo st (chấp nhận, spec §17.4). Số lạ (NaN) → 0 */
71	export const BK_WIRE = 0.8;
72	export function bkLeanToWire(lean: number): number {
73	  const w = lean * BK_WIRE, m = multiParams.drive.steerMax;
74	  return w > m ? m : w < -m ? -m : w === w ? w : 0;
75	}
76	export function bkLeanFromWire(st: number): number { return st === st ? st / BK_WIRE : 0; }
