83	// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
84	// Xe máy (D-040): drivers kèm veh + ch, joined kind 'drive' luôn vọng veh; máy chủ cũ không vọng veh thì khách xe máy trả chỗ và lái một mình
85	export type ServerMsg =
86	  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[] }
87	  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive'; veh?: number }
88	  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
89	  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
90	  | { t: 'released' };
91	
92	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
93	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
94	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
95	
96	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
97	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
98	export function exSanitizeName(raw: string): string | null {
99	  if (typeof raw !== 'string') return null;
100	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
101	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
102	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
103	  let n = 0, cps = 0;
104	  for (const g of seg.segment(s)) {
105	    let k = 0;
106	    for (const _ of g.segment) k++;
107	    cps += k;
108	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
109	  }
110	  return s;
111	}
112	/* ===== Dù lượn nhiều người: kết nối WebSocket tới máy chủ ===== */
113	import type { ClientMsg, ServerMsg } from './protocol';
114	
115	export interface Transport {
116	  send(m: ClientMsg): void;
117	  close(): void;
118	  onMessage: (m: ServerMsg) => void;
119	  onClose: () => void;
120	}
121	
122	// Mở WebSocket; reject khi lỗi hoặc quá hạn timeoutMs
123	export function exConnect(url: string, timeoutMs: number): Promise<Transport> {
124	  return new Promise<Transport>((resolve, reject) => {
125	    let ws: WebSocket;
126	    try { ws = new WebSocket(url); } catch (e) { reject(e); return; }
127	    let opened = false;
128	    let handler: ((m: ServerMsg) => void) | null = null;
129	    const pending: ServerMsg[] = [];   // tin tới trước khi người dùng gán onMessage (máy chủ gửi lobby ngay khi nhận kết nối) được giữ lại, không mất
130	    const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
131	    const t: Transport = {
132	      send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
133	      close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
134	      get onMessage() { return handler as (m: ServerMsg) => void; },
135	      set onMessage(fn: (m: ServerMsg) => void) { handler = fn; while (pending.length) fn(pending.shift() as ServerMsg); },
136	      onClose: () => {}
137	    };
138	    ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
139	    ws.onmessage = ev => {
140	      let m: ServerMsg;
141	      try { m = JSON.parse(String(ev.data)); } catch (e) { return; }
142	      if (m && typeof m.t === 'string') { if (handler) handler(m); else pending.push(m); }
143	    };
144	    ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
145	    ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
146	  });
147	}
148	/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
149	   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
150	   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
151	import type { Flyer, Kind, ServerMsg } from './protocol';
152	import type { Transport } from './client';
153	import { multiParams } from './params';
154	
155	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
156	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
157	
158	export class MultiSession {
159	  phase: Phase = 'connecting';
160	  flyers: Flyer[] = [];
161	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
162	  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
163	  mySlot = -1;
164	  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
165	  invite = false;     // đang xem và còn chỗ trống
166	  notice: Notice = '';
167	  name = '';
168	  ch = 0;             // nhân vật mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' và join xe máy (sảnh và lời mời đều qua join())
169	  veh = 0;            // loại xe của phiên 'drive': 0 ô tô (gói join như khách cũ), 1 xe máy (join kèm veh + ch; máy chủ phải vọng veh trong joined)
170	  onChange: () => void = () => {};
171	  onPos: (f: number[][]) => void = () => {};
172	  onWalkPos: (w: number[][]) => void = () => {};
173	  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
174	  private t: Transport | null = null;
175	  private disposed = false;
176	  private first = true; // chưa nhận lobby nào
177	
178	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}
179	
180	  /* Danh sách cùng loại với mình */
181	  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }
182	
183	  /* Số chỗ của nhóm cùng loại */
184	  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }
185	
186	  open(): void {
187	    this.connect().then(t => {
188	      if (this.disposed) { t.close(); return; }
189	      this.t = t;
190	      t.onMessage = m => this.recv(m);
191	      t.onClose = () => this.lost();
192	    }, () => {
193	      if (this.disposed) return;
194	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
195	    });
196	  }
197	
198	  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
199	  join(name: string): void {
200	    this.name = name; this.notice = '';
201	    if (this.kind === 'drive' && this.first) return;
202	    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : this.kind === 'walk' ? { t: 'join', name, kind: 'walk', ch: this.ch }
203	      : this.veh === 1 ? { t: 'join', name, kind: 'drive', ch: this.ch, veh: 1 } : { t: 'join', name, kind: this.kind });
204	  }
205	
206	  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
207	  leave(): void {
208	    if (this.phase !== 'flying') return;
209	    this.t?.send({ t: 'leave' });
210	    this.notice = 'released'; this.toWatching();
211	    this.onChange();
212	  }
213	
214	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
215	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
216	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
217	  }
218	
219	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
220	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
221	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
222	  }
223	
224	  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
225	  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
226	    if (this.phase !== 'flying') return;
227	    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
228	    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
229	  }
230	
231	  heartbeat(): void {
232	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
233	  }
234	
235	  dispose(): void {
236	    this.disposed = true;
237	    this.t?.close(); this.t = null;
238	  }
239	
240	  private toWatching(): void {
241	    this.phase = 'watching'; this.mySlot = -1;
242	    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
243	    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
244	    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
245	    this.fixWatched();
246	  }
247	  private mySlotWas = -1;
248	
249	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
250	  private fixWatched(): void {
251	    const ids = this.peers.map(f => f.slot);
252	    if (this.phase === 'watching') {
253	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
254	      this.invite = ids.length < this.cap;
255	    } else { this.watched = -1; this.invite = false; }
256	  }
257	
258	  private lost(): void {
259	    if (this.disposed) return;
260	    this.phase = 'solo'; this.notice = 'lost';
261	    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
262	    this.t = null; this.onChange();
263	  }
264	
265	  /* Máy chủ cũ (lobby đầu không có walkers / drivers, hoặc joined xe máy không vọng veh) không biết chỗ đi dạo / lái xe / xe máy: đóng kết nối, đi / lái một mình như khi không kết nối được */
266	  private offline(): void {
267	    const t = this.t;
268	    this.t = null;
269	    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
270	    this.phase = 'solo'; this.notice = 'offline';
271	    this.flyers = []; this.walkers = []; this.drivers = [];
272	    this.onChange();
273	  }
274	
275	  private recv(m: ServerMsg): void {
276	    if (this.disposed) return;
277	    switch (m.t) {
278	      case 'lobby':
279	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
280	        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
281	        this.flyers = m.flyers;
282	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
283	        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
284	        if (this.first) {
285	          this.first = false;
286	          if (this.peers.length >= this.cap) this.phase = 'watching';
287	          else this.phase = 'lobby';
288	        }
289	        // đang giữ chỗ: danh sách chỉ để hiển thị
290	        this.fixWatched();
291	        break;
292	      case 'joined':
293	        /* Xe máy: máy chủ cũ (trước D-040) không vọng veh và coi mình là ô tô (khách khác thấy một chiếc ô tô): trả chỗ rồi lái một mình như máy chủ không hiểu lái xe */
294	        if (this.kind === 'drive' && this.veh === 1 && typeof m.veh !== 'number') { this.t?.send({ t: 'leave' }); this.offline(); return; }
295	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
296	        this.fixWatched();
297	        break;
298	      case 'rejected':
299	        if (m.why === 'name') this.notice = 'nameBad';
300	        else {
301	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
302	          this.phase = 'watching';
303	          this.fixWatched();
304	        }
305	        break;
306	      case 'pos':
307	        this.onPos(m.f);
308	        if (Array.isArray(m.w)) this.onWalkPos(m.w);
309	        if (Array.isArray(m.d)) this.peersDrive(m.d);
310	        return;
311	      case 'released':
312	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
313	        break;
314	    }
315	    this.onChange();
316	  }
317	}
