533	/* ===== Dù lượn, đi dạo và lái xe nhiều người: nhãn tên nổi cạnh người chơi khác =====
534	   Một div cho mỗi slot bay, mỗi slot đi dạo và mỗi slot lái xe trong #exMpLabels (theo thứ tự đó). Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
535	   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu); xe: trên nóc, cao hơn mặt đường car.height + drive.remote.labelAbove m (xe máy: bike.body.height + bike.remote.labelAbove, trên mũ người lái). Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
536	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
537	import * as THREE from 'three';
538	import { CONFIG } from '../../config';
539	import type { exRemotes } from './remote';
540	import type { stAvatars } from '../stroll/avatars';
541	import type { exDrivers } from './remoteDrive';
542	
543	const M = CONFIG.explore.multi, NW = M.stroll.slots, ND = M.drive.slots, CAR_TOP = CONFIG.drive.car.height + CONFIG.drive.remote.labelAbove, BIKE_TOP = CONFIG.bike.body.height + CONFIG.bike.remote.labelAbove;
544	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
545	let labs: Lab[] | null = null;   // M.slots nhãn dù, NW nhãn người đi dạo rồi ND nhãn xe
546	const _v = new THREE.Vector3();
547	
548	function init(): Lab[] | null {
549	  const box = document.getElementById('exMpLabels');
550	  if (!box) return null;
551	  return Array.from({ length: M.slots + NW + ND }, () => {
552	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
553	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
554	  });
555	}
556	
557	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
558	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
559	
560	/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
561	function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
562	  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
563	  if (-_v.z <= 0.1) return false;   // sau camera
564	  _v.applyMatrix4(camera.projectionMatrix);
565	  const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
566	  if (px <= -80 || px >= w + 80 || py <= -40 || py >= h + 40) return false;
567	  if (nowMs - L.tMs >= 200) {
568	    L.tMs = nowMs;
569	    const txt = `${name} · ${dist(Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z))}`;
570	    if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
571	  }
572	  if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
573	  return true;
574	}
575	
576	export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number, walkers?: typeof stAvatars, drivers?: typeof exDrivers): void {
577	  if (!labs && !(labs = init())) return;
578	  const w = window.innerWidth, h = window.innerHeight;
579	  for (let i = 0; i < M.slots; i++) {
580	    const L = labs[i], st = remotes.slotState(i);
581	    const vis = !!st && place(L, camera, st.pos.x, st.pos.y - M.labelBelow, st.pos.z, remotes.name(i), nowMs, w, h);
582	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
583	  }
584	  for (let i = 0; i < NW; i++) {
585	    const L = labs[M.slots + i], st = walkers && i !== walkers.self ? walkers.slotState(i) : null, nm = st ? walkers!.name(i) : null;
586	    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CONFIG.stroll.labelAbove, st.z, nm, nowMs, w, h);
587	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
588	  }
589	  for (let i = 0; i < ND; i++) {
590	    const L = labs[M.slots + NW + i], st = drivers ? drivers.slotState(i) : null, nm = st ? drivers!.name(i) : null;   // xe của mình không có trong exDrivers (slotState null)
591	    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + (drivers!.vehOf?.(i) === 1 ? BIKE_TOP : CAR_TOP), st.z, nm, nowMs, w, h);
592	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
593	  }
594	}
