597	export function exLabelsClear(): void {
598	  if (!labs) return;
599	  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
600	}
601	/* ===== Dù lượn nhiều người: đếm thời gian rời máy (không DOM, không timer; người gọi đưa mốc thời gian vào) =====
602	   Không chạm phím idleMs thì 'warn' (hỏi "Bạn còn đó không?"), thêm idleWarnMs nữa thì 'expired' (trả slot). */
603	export type IdleState = 'ok' | 'warn' | 'expired';
604	
605	export class ExIdle {
606	  private last = 0;   // ms — mốc phím cuối (hoặc mốc reset)
607	  constructor(private idleMs: number, private warnMs: number) {}
608	
609	  activity(now: number): void { this.last = now; }
610	  reset(now: number): void { this.last = now; }
611	
612	  tick(now: number): IdleState {
613	    const d = now - this.last;
614	    return d < this.idleMs ? 'ok' : d < this.idleMs + this.warnMs ? 'warn' : 'expired';
615	  }
616	
617	  /* Số giây còn lại tới lúc hết hạn, làm tròn lên (không âm) */
618	  remaining(now: number): number {
619	    return Math.max(0, Math.ceil((this.idleMs + this.warnMs - (now - this.last)) / 1000));
620	  }
621	}
622	/* ===== Nhiều người: khóa chữ và số chỗ theo loại phiên (không DOM, không three) =====
623	   Sảnh (lobby.ts) và giao diện xem (watch.ts) dùng chung một bộ chữ cho ba loại: dù lượn (exMp*), đi dạo (st*), lái xe (dr*).
624	   `full` (chữ "đã đủ người") chỉ có ở đi dạo và lái xe: dù lượn đầy chỗ thì sảnh chuyển ngay sang chế độ xem. */
625	import { multiParams } from './params';
