627	
628	export interface ExMpKeys { sky: string; go: string; solo: string; offline: string; seats: string; full: string | null; invite: string; inviteGo: string; watching: string; late: string; released: string; lost: string }
629	
630	const KEYS: Record<Kind, ExMpKeys> = {
631	  fly: { sky: 'exMpSky', go: 'exMpFly', solo: 'exMpSolo', offline: 'exMpOffline', seats: 'exMpSeats', full: null, invite: 'exMpInvite', inviteGo: 'exMpInviteFly', watching: 'exMpWatching', late: 'exMpLate', released: 'exMpReleased', lost: 'exMpLost' },
632	  walk: { sky: 'stSky', go: 'stGo', solo: 'stSolo', offline: 'stOffline', seats: 'stSeats', full: 'stFull', invite: 'stInvite', inviteGo: 'stInviteGo', watching: 'stWatch', late: 'stLate', released: 'stReleased', lost: 'stLost' },
633	  drive: { sky: 'stSky', go: 'drGo', solo: 'drSolo', offline: 'drOffline', seats: 'drSeats', full: 'drFull', invite: 'drInvite', inviteGo: 'drInviteGo', watching: 'drWatch', late: 'drLate', released: 'drReleased', lost: 'drLost' }
634	};
